import math, importlib.util
spec = importlib.util.spec_from_file_location("cn", "convnet.py")
cn = importlib.util.module_from_spec(spec); spec.loader.exec_module(cn)
x, labels, _ = cn._load_bench_samples(cn._BENCH_TRAIN_PATH)

def ce(logits, labs):
    tot=0.0
    for n,row in enumerate(logits):
        m=max(row); exps=[math.exp(v-m) for v in row]; d=sum(exps)
        tot += -math.log(exps[labs[n]]/d)
    return tot/len(logits)

def run(make_probe):
    layers = cn._build_norm_layers()
    probe = make_probe(layers)
    n_=len(x); s=7; series=[]
    for ep in range(20):
        order=[0,1]
        for i in range(n_-1,0,-1):
            s=(1664525*s+1013904223)%4294967296
            j=s%(i+1); order[i],order[j]=order[j],order[i]
        for start in range(0,n_,1):
            idx=order[start:start+1]
            bx=[x[k] for k in idx]; bl=[labels[k] for k in idx]
            series.append(probe(bx, bl))
            cn.train_norm_step(layers, bx, bl, 0.1)
    return series

def infer_logits(layers, xx):
    conv, bn, _, _, _, lin, _ = layers
    return cn._norm_forward(conv._weights, conv._bias, bn._gamma, bn._beta,
        bn.running_mean, bn.running_var, lin._weights, lin._bias, xx, False)[0]

# G: singleton current batch, eval mode w/ current running stats
def probe_g(layers):
    def p(bx, bl): return ce(infer_logits(layers, bx), bl)
    return p

# B: full set, eval mode w/ current running stats
def probe_b(layers):
    def p(bx, bl): return ce(infer_logits(layers, x), labels)
    return p

# H: full set, running stats refreshed by train-mode full-batch BN fwd (snapshot restore)
def probe_h(layers):
    conv, bn = layers[0], layers[1]
    def p(bx, bl):
        snap = cn._snapshot_layers(layers)
        try:
            bn.forward(conv.forward(x))
            return ce(infer_logits(layers, x), labels)
        finally:
            cn._restore_layers(layers, snap)
    return p

for name, mk in [("G_singleton_eval_running", probe_g),
                 ("B_full_eval_running", probe_b),
                 ("H_full_eval_refreshed", probe_h)]:
    ser = run(mk)
    print("%-28s first=%.6f last=%.6f ok=%s" % (name, ser[0], ser[-1], ser[-1]<ser[0]))
    print("  ", ["%.3f"%v for v in ser])
