        m = row[0]
        for o in range(1, _CNN_NUM_CLASSES):
            if row[o] > m:
                m = row[o]
        denom = 0.0
        for o in range(_CNN_NUM_CLASSES):
            denom += math.exp(row[o] - m)
        total += m + math.log(denom) - row[labels[n]]
